def generate_general_ledger():
    n_rows = 2500
    accounts = {
        '6011': "Achats matières premières", '6012': "Achats fournitures",
        '6022': "Énergie et fluides", '6132': "Entretien et réparations",
        '6141': "Matériel informatique", '6142': "Licences logicielles",
        '6160': "Services extérieurs", '6171': "Transport sur ventes",
        '6172': "Frais logistiques", '6182': "Primes d'assurance",
        '6200': "Charges sociales", '6210': "Frais de formation",
        '6310': "Publicité et marketing", '6411': "Salaires bruts",
        '6441': "Charges patronales", '6512': "Honoraires de gestion",
        '6613': "Charges d'intérêts"
    }
    depts = ['Procurement', 'Finance', 'HR', 'IT', 'Production', 'Logistics', 'Sales', 'Administration']
    dept_weights = [0.22, 0.12, 0.08, 0.10, 0.25, 0.12, 0.07, 0.04]
    dept_abbr = {'Procurement':'PR', 'Finance':'FI', 'HR':'HR', 'IT':'IT', 'Production':'PD', 'Logistics':'LG', 'Sales':'SL', 'Administration':'AD'}
    gl_vendor_bank = [v for v in vendor_bank if v not in ['MECATELEC SARL', 'NEXANS MAROC']]
    
    rows = []
    for i in range(n_rows):
        date = datetime(2024,1,1) + timedelta(days=random.randint(0,364))
        j_id = f"JNL-{i+1:05d}"
        acc_code = random.choice(list(accounts.keys()))
        acc_name = accounts[acc_code]
        dept = random.choices(depts, weights=dept_weights)[0]
        vendor = random.choice(gl_vendor_bank)
        
        while True:
            amt_rand = random.random()
            if amt_rand < 0.60: amt = round(random.uniform(500, 15000), 2)
            elif amt_rand < 0.85: amt = round(random.uniform(15000, 80000), 2)
            else: amt = round(random.uniform(80000, 350000), 2)
            if not (9100 <= amt <= 9870) and not (48200 <= amt <= 49750):
                break
        
        entry = random.choices(['Debit', 'Credit'], weights=[0.72, 0.28])[0]
        desc = f"{dept} - {acc_name} - {date.strftime('%Y-%m')}"
        approver = f"MGR-{dept_abbr[dept]}-0{random.randint(1,5)}"
        pay_method = random.choices(['Virement bancaire','Chèque','Espèces','Prélèvement'], weights=[0.60, 0.25, 0.08, 0.07])[0]
        
        rows.append({
            'Date': date, 'Journal_ID': j_id, 'Account_Code': acc_code, 'Account_Name': acc_name,
            'Department': dept, 'Vendor_Customer': vendor, 'Amount_MAD': amt, 'Entry_Type': entry,
            'Description': desc, 'Approver_ID': approver, 'Payment_Method': pay_method
        })
        
    df = pd.DataFrame(rows)
    
    # SIGNAL 1 — Duplicate Payments (14 pairs = 28 rows affected)
    proc_indices = df[df['Department'] == 'Procurement'].index.tolist()
    dup_indices = random.sample(proc_indices, 28)
    used_indices = set(dup_indices)
    for i in range(14):
        idx1 = dup_indices[i*2]
        idx2 = dup_indices[i*2+1]
        amt = round(random.uniform(7500, 14800), 2)
        date1 = df.at[idx1, 'Date']
        date2 = date1 + timedelta(days=random.randint(2,6))
        for idx, d in zip([idx1, idx2], [date1, date2]):
            df.at[idx, 'Vendor_Customer'] = 'MECATELEC SARL'
            df.at[idx, 'Amount_MAD'] = amt
            df.at[idx, 'Date'] = d
            df.at[idx, 'Department'] = 'Production'
            df.at[idx, 'Description'] = f"Production - Services extérieurs - {d.strftime('%Y-%m')}"
            df.at[idx, 'Account_Code'] = '6160'
            df.at[idx, 'Account_Name'] = accounts['6160']
            
    # SIGNAL 2 — Threshold Avoidance — 10k (23 rows)
    avail = [i for i in range(n_rows) if i not in used_indices]
    thresh10k_idx = random.sample(avail, 23)
    used_indices.update(thresh10k_idx)
    for i, idx in enumerate(thresh10k_idx):
        df.at[idx, 'Amount_MAD'] = round(random.uniform(9100, 9870), 2)
        dept = 'Procurement' if i < 15 else 'Logistics'
        df.at[idx, 'Department'] = dept
        df.at[idx, 'Approver_ID'] = 'MGR-PR-01' if dept == 'Procurement' else 'MGR-LG-02'
        
    # SIGNAL 3 — Threshold Avoidance — 50k (11 rows)
    avail = [i for i in range(n_rows) if i not in used_indices]
    thresh50k_idx = random.sample(avail, 11)
    used_indices.update(thresh50k_idx)
    for idx in thresh50k_idx:
        df.at[idx, 'Amount_MAD'] = round(random.uniform(48200, 49750), 2)
        df.at[idx, 'Department'] = 'Procurement'
        df.at[idx, 'Approver_ID'] = 'MGR-PR-02'
        
    # SIGNAL 4 — Supplier Concentration NEXANS
    proc_all = df[df['Department'] == 'Procurement'].index.tolist()
    avail_proc = [i for i in proc_all if i not in used_indices]
    nexans_count = int(len(proc_all) * 0.18)
    nexans_idx = random.sample(avail_proc, min(nexans_count, len(avail_proc)))
    used_indices.update(nexans_idx)
    for idx in nexans_idx:
        df.at[idx, 'Vendor_Customer'] = 'NEXANS MAROC'
        df.at[idx, 'Amount_MAD'] = round(random.uniform(45000, 180000), 2)
        df.at[idx, 'Account_Code'] = '6011'
        df.at[idx, 'Account_Name'] = 'Achats matières premières'
        
    # SIGNAL 5 — Legacy ERP Maintenance (3 rows)
    it_rows = df[df['Department'] == 'IT'].index.tolist()
    avail_it = [i for i in it_rows if i not in used_indices][:3]
    used_indices.update(avail_it)
    months_sap = ['03', '06', '09']
    for idx, m in zip(avail_it, months_sap):
        df.at[idx, 'Vendor_Customer'] = 'SAP MAROC'
        df.at[idx, 'Amount_MAD'] = round(random.uniform(258000, 285000), 2)
        df.at[idx, 'Description'] = f"IT - Legacy ERP Maintenance Contract - 2024-{m}"
        df.at[idx, 'Account_Code'] = '6142'
        df.at[idx, 'Account_Name'] = 'Licences logicielles'
        df.at[idx, 'Approver_ID'] = 'MGR-IT-01'
        
    # SIGNAL 6 — Benford's Law Anomaly Logistics
    log_rows = df[df['Department'] == 'Logistics'].index.tolist()
    avail_log = [i for i in log_rows if i not in used_indices]
    benford_count = int(len(log_rows) * 0.22)
    benford_idx = random.sample(avail_log, min(benford_count, len(avail_log)))
    for idx in benford_idx:
        magnitude = 10 ** random.randint(2, 4)
        df.at[idx, 'Amount_MAD'] = round(6 * magnitude + random.uniform(100, magnitude-1), 2)
        
    out_path = os.path.join(DATA_DIR, 'general_ledger.xlsx')
    df.to_excel(out_path, index=False)
    print(f"[OK] general_ledger.xlsx saved — {len(df)} rows")

def generate_supplier_master():
    rows = []
    adjs = ['ATLAS','MAGHREB','ROYAL','CASABLANCA','KENITRA','NORTH AFRICA','IMPERIAL','MERIDIAN','ALLIANCE','PREMIER']
    inds = ['INDUSTRIES','TECHNOLOGIES','SERVICES','LOGISTICS','ENGINEERING','SOLUTIONS','TRADING','SUPPLIES','SYSTEMS','CONSULTING']
    
    for i in range(180):
        s_id = f"SUPP-{i+1:03d}"
        if i == 0: name = "NEXANS MAROC"
        elif i == 1: name = "YAZAKI MOROCCO"
        elif i == 2: name = "SUMITOMO ELECTRIC WIRING"
        elif i < 46: name = vendor_bank[i+2] if i+2 < len(vendor_bank) else vendor_bank[-1]
        else: name = f"{random.choice(adjs)} {random.choice(inds)} MAROC SARL"
        
        if i <= 2: ctry = "Morocco"
        elif 12 <= i <= 15: ctry = "Germany"
        else: ctry = random.choices(['Morocco','France','Spain','Italy','China','Portugal','Germany','USA','Japan','South Korea'], weights=[0.45,0.18,0.10,0.08,0.07,0.04,0.03,0.02,0.02,0.01])[0]
        
        cat = random.choices(['Matières premières câblage','Services IT','Logistique & transport','Équipements industriels','Fournitures bureau','Services RH','Maintenance','Conseil & audit','Énergie','Formation'], weights=[0.25,0.12,0.15,0.15,0.08,0.07,0.08,0.05,0.03,0.02])[0]
        
        if 3 <= i <= 11: amt = round(random.uniform(800000, 3500000), 2)
        elif 12 <= i <= 15: amt = round(random.uniform(600000, 1200000), 2)
        elif 16 <= i <= 60: amt = round(random.uniform(150000, 800000), 2)
        elif i > 60: amt = round(random.uniform(10000, 150000), 2)
        else: amt = 0 # 0, 1, 2 set later
        
        if 3 <= i <= 11: ss = 'Y'
        else: ss = random.choices(['Y','N'], weights=[0.12,0.88])[0]
        
        start = (datetime(2018,1,1) + timedelta(days=random.randint(0, 1825))).strftime('%Y-%m-%d')
        
        if 12 <= i <= 15: exp = (datetime(2025,8,1) + timedelta(days=random.randint(0,55))).strftime('%Y-%m-%d')
        else: exp = (datetime(2024,6,1) + timedelta(days=random.randint(0,1309))).strftime('%Y-%m-%d')
        
        if 3 <= i <= 5: aud = '2020-03-15'
        elif 6 <= i <= 8: aud = '2019-11-20'
        elif 9 <= i <= 11: aud = '2020-08-10'
        elif 0 <= i <= 2: aud = '2024-06-15'
        else: aud = (datetime(2021,1,1) + timedelta(days=random.randint(0, 1399))).strftime('%Y-%m-%d')
        
        pt = random.choices([30, 45, 60, 90], weights=[0.20, 0.15, 0.50, 0.15])[0]
        iso = 'Y' if i <= 11 else random.choices(['Y','N'], weights=[0.62, 0.38])[0]
        
        # Risk rating
        if ss == 'Y' and int(aud[:4]) < 2021: risk = 'High'
        elif i <= 2: risk = 'Medium'
        elif '2025' in exp and ctry == 'Germany': risk = 'High'
        elif iso == 'N' and amt > 500000: risk = 'High'
        else: risk = random.choices(['Low','Medium','High'], weights=[0.55,0.35,0.10])[0]
        
        rows.append({
            'Supplier_ID': s_id, 'Supplier_Name': name, 'Country': ctry, 'Category': cat, 'Annual_Spend_MAD': amt,
            'Single_Source': ss, 'Contract_Start': start, 'Contract_Expiry': exp, 'Last_Audit_Date': aud,
            'Payment_Terms_Days': pt, 'ISO_Certified': iso, 'Risk_Rating': risk
        })
        
    df = pd.DataFrame(rows)
    total_3_179 = df.loc[3:, 'Annual_Spend_MAD'].sum()
    total_all = total_3_179 / 0.27
    df.at[0, 'Annual_Spend_MAD'] = round(total_all * 0.38, 2)
    df.at[1, 'Annual_Spend_MAD'] = round(total_all * 0.21, 2)
    df.at[2, 'Annual_Spend_MAD'] = round(total_all * 0.14, 2)
    
    out_path = os.path.join(DATA_DIR, 'supplier_master.csv')
    df.to_csv(out_path, index=False)
    print(f"[OK] supplier_master.csv saved — {len(df)} rows")

def generate_payroll():
    # Employee Master
    emp_rows = []
    suffixes = ['', ' I', ' II', ' III', ' IV', ' V', ' VI', ' VII', ' VIII']
    dept_counts = {'Production':160, 'Logistics':48, 'Sales':32, 'Procurement':28, 'IT':20, 'Finance':16, 'HR':12, 'Administration':4}
    depts_flat = []
    for d, c in dept_counts.items(): depts_flat.extend([d]*c)
    random.shuffle(depts_flat)
    
    for i in range(320):
        e_id = f"E{i+1:04d}"
        name = names_bank[i % 40] + suffixes[i // 40]
        dept = depts_flat[i]
        
        if dept == 'Production':
            grade = random.choices(['OP1','OP2','OP3','TL1','TL2'], weights=[0.30,0.30,0.20,0.12,0.08])[0]
            if 'OP' in grade: sal = round(random.uniform(2800, 4200), 2)
            else: sal = round(random.uniform(4200, 6500), 2)
        elif dept in ['Finance', 'HR', 'Administration']:
            grade = random.choices(['A1','A2','A3','M1','M2'], weights=[0.25,0.30,0.25,0.15,0.05])[0]
            sal = round(random.uniform(6000, 18000), 2)
        elif dept == 'IT':
            grade = random.choices(['IT1','IT2','IT3','ITSR','ITML'], weights=[0.20,0.30,0.25,0.20,0.05])[0]
            sal = round(random.uniform(8000, 25000), 2)
        elif dept in ['Procurement', 'Sales']:
            grade = random.choices(['M1','M2','M3','D1','D2'], weights=[0.30,0.35,0.20,0.12,0.03])[0]
            if dept == 'Sales': sal = round(random.uniform(5000, 15000), 2)
            else: sal = round(random.uniform(7000, 22000), 2)
        elif dept == 'Logistics':
            grade = random.choices(['OP1','OP2','OP3','TL1','TL2'], weights=[0.30,0.30,0.20,0.12,0.08])[0]
            sal = round(random.uniform(3500, 7000), 2)
            
        start = (datetime(2010,1,1) + timedelta(days=random.randint(0, 4928))).strftime('%Y-%m-%d')
        
        if e_id in ['E0291', 'E0305']: status = 'Terminated'
        elif e_id in ['E0047', 'E0183']: status = 'Active'
        else:
            if i < 8: status = 'On_Leave'
            else: status = random.choices(['Active','Terminated'], weights=[0.93,0.07])[0]
            
        mgr = f"MGR-{'PR' if dept=='Procurement' else 'FI' if dept=='Finance' else 'HR' if dept=='HR' else 'IT' if dept=='IT' else 'PD' if dept=='Production' else 'LG' if dept=='Logistics' else 'SL' if dept=='Sales' else 'AD'}"
        loc = 'Casablanca' if dept == 'Sales' else 'Kenitra'
        
        emp_rows.append({'Employee_ID': e_id, 'Full_Name': name, 'Department': dept, 'Grade': grade, 'Base_Salary_MAD': sal, 'Start_Date': start, 'Status': status, 'Manager_ID': mgr, 'Location': loc})
        
    df_emp = pd.DataFrame(emp_rows)
    
    # Monthly Transactions
    txn_rows = []
    txn_idx = 1
    bank_refs = {e['Employee_ID']: f"MA{random.randint(100000,999999)}{random.randint(1000000,9999999)}" for e in emp_rows}
    
    for m in range(1, 13):
        month_str = f"2024-{m:02d}"
        for e in emp_rows:
            if e['Status'] != 'Active' and e['Employee_ID'] not in ['E0047', 'E0183', 'E0291', 'E0305']:
                continue
            
            # Skip ghosts except Nov/Dec
            if e['Employee_ID'] in ['E0291', 'E0305'] and month_str not in ['2024-11', '2024-12']:
                continue
            
            p_by = random.choice(['ADMIN_RH_01','ADMIN_RH_02','ADMIN_RH_03'])
            if e['Employee_ID'] in ['E0291', 'E0305']: p_by = 'ADMIN_RH_03'
            
            # Base salary
            txn_rows.append({
                'Transaction_ID': f"TXN-2024-{txn_idx:05d}", 'Month': month_str, 'Employee_ID': e['Employee_ID'],
                'Payment_Type': 'Salaire', 'Amount_MAD': e['Base_Salary_MAD'], 'Payment_Date': f"2024-{m:02d}-28",
                'Processed_By': p_by, 'Bank_Account_Ref': bank_refs[e['Employee_ID']]
            })
            txn_idx += 1
            
            # Duplicates in Oct for E0047, E0183
            if month_str == '2024-10' and e['Employee_ID'] in ['E0047', 'E0183']:
                txn_rows.append({
                    'Transaction_ID': f"TXN-2024-{txn_idx:05d}", 'Month': month_str, 'Employee_ID': e['Employee_ID'],
                    'Payment_Type': 'Salaire', 'Amount_MAD': e['Base_Salary_MAD'], 'Payment_Date': f"2024-{m:02d}-29",
                    'Processed_By': 'ADMIN_RH_02', 'Bank_Account_Ref': f"MA{random.randint(100000,999999)}{random.randint(1000000,9999999)}"
                })
                txn_idx += 1
                
            # Bonus
            if e['Status'] == 'Active' and random.random() < 0.20:
                txn_rows.append({
                    'Transaction_ID': f"TXN-2024-{txn_idx:05d}", 'Month': month_str, 'Employee_ID': e['Employee_ID'],
                    'Payment_Type': 'Prime', 'Amount_MAD': round(e['Base_Salary_MAD']*random.uniform(0.05,0.15), 2), 
                    'Payment_Date': f"2024-{m:02d}-28", 'Processed_By': p_by, 'Bank_Account_Ref': bank_refs[e['Employee_ID']]
                })
                txn_idx += 1
            
            # Overtime
            if e['Status'] == 'Active' and random.random() < 0.05:
                txn_rows.append({
                    'Transaction_ID': f"TXN-2024-{txn_idx:05d}", 'Month': month_str, 'Employee_ID': e['Employee_ID'],
                    'Payment_Type': 'Heures supplémentaires', 'Amount_MAD': round(e['Base_Salary_MAD']*random.uniform(0.02,0.08), 2), 
                    'Payment_Date': f"2024-{m:02d}-28", 'Processed_By': p_by, 'Bank_Account_Ref': bank_refs[e['Employee_ID']]
                })
                txn_idx += 1
                
    df_txn = pd.DataFrame(txn_rows)
    
    # Summary
    sum_rows = []
    for m in range(1, 13):
        month_str = f"2024-{m:02d}"
        m_data = df_txn[df_txn['Month'] == month_str]
        salaries = m_data[m_data['Payment_Type'] == 'Salaire']['Amount_MAD'].sum()
        primes = m_data[m_data['Payment_Type'] == 'Prime']['Amount_MAD'].sum()
        heures = m_data[m_data['Payment_Type'] == 'Heures supplémentaires']['Amount_MAD'].sum()
        hc = m_data['Employee_ID'].nunique()
        total = salaries + primes + heures
        sum_rows.append({
            'Month': month_str, 'Total_Headcount_Paid': hc, 'Total_Salaires_MAD': salaries,
            'Total_Primes_MAD': primes, 'Total_Heures_Supp_MAD': heures, 'Total_Payroll_MAD': total,
            'Vs_Budget_Pct': round(random.uniform(98.2, 103.5), 1)
        })
    df_sum = pd.DataFrame(sum_rows)
    
    out_path = os.path.join(DATA_DIR, 'payroll.xlsx')
    with pd.ExcelWriter(out_path) as writer:
        df_emp.to_excel(writer, sheet_name='Employee_Master', index=False)
        df_txn.to_excel(writer, sheet_name='Monthly_Transactions', index=False)
        df_sum.to_excel(writer, sheet_name='Summary', index=False)
    print(f"[OK] payroll.xlsx saved — Employee_Master: {len(df_emp)}, TXN: {len(df_txn)}, Sum: {len(df_sum)} rows")

def generate_kpi_data():
    rows = []
    for i in range(24):
        y = 2023 if i < 12 else 2024
        m = (i % 12) + 1
        month = f"{y}-{m:02d}"
        
        prod_vol = random.randint(118000, 132000) if y == 2023 else random.randint(124000, 145000)
        
        def_base = 1.2 + (i * (3.9 - 1.2) / 23)
        def_rate = max(1.0, round(def_base + random.uniform(-0.08, 0.08), 2))
        
        if y == 2023: otd = round(random.uniform(91.0, 96.5), 1)
        elif m <= 6: otd = round(random.uniform(88.0, 93.0), 1)
        else: otd = round(random.uniform(84.0, 90.0), 1)
        
        turnover = round(random.uniform(7.5, 11.0), 1) if y == 2023 else round(random.uniform(12.0, 16.5), 1)
        
        if month == '2024-09': it_down = 63
        else: it_down = random.randint(2, 12)
        
        cust_comp = random.randint(12, 28) if y == 2023 else random.randint(22, 48)
        rev = round(random.uniform(58000000, 64000000), 2) if y == 2023 else round(random.uniform(61000000, 68000000), 2)
        op_cost = round(random.uniform(48000000, 54000000), 2) if y == 2023 else round(random.uniform(53000000, 60000000), 2)
        ebitda = round((rev - op_cost) / rev * 100, 1)
        scrap = round(def_rate * 0.65 + random.uniform(-0.1, 0.1), 2)
        new_sup = random.randint(0, 3)
        sup_comp = random.randint(1, 8)
        
        row = {
            'Month': month, 'Production_Volume_Units': prod_vol, 'Defect_Rate_Pct': def_rate,
            'On_Time_Delivery_Pct': otd, 'Employee_Turnover_Pct': turnover, 'IT_Downtime_Hours': it_down,
            'Customer_Complaints_Count': cust_comp, 'Revenue_MAD': rev, 'Operating_Cost_MAD': op_cost,
            'EBITDA_Margin_Pct': ebitda, 'Scrap_Rate_Pct': scrap, 'New_Suppliers_Onboarded': new_sup,
            'Supplier_Complaints_Count': sup_comp
        }
        if month == '2024-09': row['Comment'] = "ERP System Critical Failure"
        rows.append(row)
        
    df = pd.DataFrame(rows)
    out_path = os.path.join(DATA_DIR, 'kpi_data.xlsx')
    df.to_excel(out_path, index=False)
    print(f"[OK] kpi_data.xlsx saved — {len(df)} rows")

