def make_bg_watermark(canvas, doc):
    canvas.saveState()
    canvas.setFont('Helvetica', 60)
    canvas.setFillGray(0.9)
    canvas.translate(297, 420)
    canvas.rotate(45)
    canvas.drawCentredString(0, 0, "CONFIDENTIEL")
    canvas.restoreState()
    canvas.setFont('Helvetica', 9)
    canvas.drawString(inch, 0.75 * inch, f"Page {doc.page} sur 10")

inch = 2.54 * cm

def generate_procurement_policy():
    out_path = os.path.join(DATA_DIR, 'procurement_policy.pdf')
    doc = SimpleDocTemplate(out_path, pagesize=A4)
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(name='CustomTitle', parent=styles['Heading1'], fontName='Helvetica-Bold', fontSize=16, alignment=TA_CENTER, spaceAfter=20)
    h2_style = ParagraphStyle(name='CustomH2', parent=styles['Heading2'], fontName='Helvetica-Bold', fontSize=12, spaceAfter=10, spaceBefore=15)
    body_style = ParagraphStyle(name='CustomBody', parent=styles['Normal'], fontName='Helvetica', fontSize=10, alignment=TA_JUSTIFY, spaceAfter=10)
    
    story = []
    
    story.append(Paragraph("MERIDIAN CABLES MAROC SA", title_style))
    story.append(Paragraph("POLITIQUE ACHATS ET APPROVISIONNEMENT", title_style))
    story.append(Paragraph("Document N°: POL-ACH-2021-003<br/>Version: 3.2<br/>Date de dernière révision: 14 Septembre 2021<br/>Date de prochaine révision prévue: Septembre 2023 [OVERDUE]<br/>Propriétaire: Direction des Achats<br/>Classification: Interne", body_style))
    story.append(Spacer(1, 20))
    
    story.append(Paragraph("Section 1 — Objet et Champ d'Application (Purpose and Scope)", h2_style))
    story.append(Paragraph("La présente politique couvre l'ensemble des activités d'achat et d'approvisionnement pour Meridian Cables Maroc SA. Elle s'applique à tous les départements disposant d'une autorité d'achat, garantissant que nos pratiques sont conformes aux exigences de gestion de la qualité ISO 9001:2015. Il est impératif que tous les achats assurent un excellent rapport qualité-prix, une transparence totale dans le processus de sélection, et un alignement strict avec la stratégie globale de l'entreprise. Cette politique sert de guide fondamental pour toutes les interactions avec nos partenaires commerciaux.", body_style))
    
    story.append(Paragraph("Section 2 — Critères de Sélection des Fournisseurs (Supplier Selection)", h2_style))
    story.append(Paragraph("Un minimum de trois devis compétitifs est exigé pour tout achat dépassant 50 000 MAD. La liste des fournisseurs agréés doit être systématiquement consultée avant toute nouvelle commande. Les critères de sélection incluent impérativement la stabilité financière du partenaire, ses certifications de qualité, et sa fiabilité de livraison éprouvée au fil du temps. La certification ISO est fortement privilégiée lors de l'évaluation initiale.", body_style))
    
    story.append(Paragraph("Section 3 — Matrice d'Autorisation (Approval Authority Matrix)", h2_style))
    data = [
        ['Montant', "Niveau d'approbation requis"],
        ['< 10,000 MAD', 'Responsable de département'],
        ['10,001 - 50,000 MAD', 'Directeur de département'],
        ['50,001 - 200,000 MAD', 'Directeur Financier (CFO)'],
        ['> 200,000 MAD', 'Comité de direction']
    ]
    t = Table(data, style=[('GRID',(0,0),(-1,-1),1,rl_colors.black),('BACKGROUND',(0,0),(-1,0),rl_colors.lightgrey),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold')])
    story.append(t)
    story.append(Spacer(1, 10))
    
    story.append(Paragraph("Section 4 — Gestion des Contrats (Contract Management)", h2_style))
    story.append(Paragraph("Tous les contrats dont le montant dépasse 100 000 MAD exigent une révision minutieuse par le Département Juridique avant toute signature. Les conditions contractuelles standard stipulent un paiement net à 60 jours. Les renouvellements de contrats nécessitent un nouvel appel d'offres compétitif après une période de trois ans. Le registre des contrats est maintenu et mis à jour rigoureusement par le département des Achats.", body_style))
    
    story.append(Paragraph("Section 5 — Délais de Paiement (Payment Terms)", h2_style))
    story.append(Paragraph("Les délais de paiement standard sont fixés à 60 jours francs. Une remise pour paiement anticipé peut être négociée au cas par cas avec la validation du service financier. Tous les paiements excédant 10 000 MAD doivent impérativement être effectués par virement bancaire pour assurer la traçabilité. Les paiements en espèces sont strictement interdits pour les montants supérieurs à 5 000 MAD.", body_style))
    
    story.append(Paragraph("Section 6 — Éthique et Déontologie (Ethics)", h2_style))
    story.append(Paragraph("L'entreprise applique une politique de tolérance zéro face à la corruption et aux pratiques anticoncurrentielles. Une déclaration annuelle de conflits d'intérêts est obligatoire pour tout le personnel impliqué dans le processus d'achat. Les cadeaux provenant de fournisseurs dont la valeur dépasse 500 MAD doivent être déclarés au service conformité. Tout manquement à ces règles entraînera des mesures disciplinaires sévères.", body_style))
    
    story.append(Paragraph("Section 7 — Fournisseurs Source Unique (Single-Source Suppliers)", h2_style))
    story.append(Paragraph("Le recours aux fournisseurs à source unique est autorisé exclusivement lorsque les spécifications techniques sont uniques, en situation de monopole sur le marché, ou dans des cas d'approvisionnement d'urgence avérés. Tous les arrangements avec une source unique doivent être documentés de manière exhaustive avec une justification commerciale claire et validée par la direction.", body_style))
    
    story.append(Paragraph("Section 8 — Révision et Contrôle de la Politique", h2_style))
    story.append(Paragraph("La présente politique fait l'objet d'une révision annuelle sous la supervision du Directeur des Achats, afin de garantir son adéquation continue avec les pratiques du marché et les objectifs de l'entreprise. La prochaine révision est programmée pour Septembre 2023.", body_style))
    
    # Pad to make it longer
    for _ in range(5):
        story.append(PageBreak())
        story.append(Paragraph("Section Annexe — Dispositions Générales", h2_style))
        story.append(Paragraph("Ces dispositions supplémentaires servent à compléter les cadres établis dans les sections précédentes, en offrant des lignes directrices pour les situations exceptionnelles qui pourraient survenir lors de nos opérations d'approvisionnement régulières. " * 10, body_style))
    
    doc.build(story, onFirstPage=make_bg_watermark, onLaterPages=make_bg_watermark)
    print("[OK] procurement_policy.pdf saved")

def generate_it_security_policy():
    out_path = os.path.join(DATA_DIR, 'it_security_policy.pdf')
    doc = SimpleDocTemplate(out_path, pagesize=A4)
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(name='CustomTitle', parent=styles['Heading1'], fontName='Helvetica-Bold', fontSize=16, alignment=TA_CENTER, spaceAfter=20)
    h2_style = ParagraphStyle(name='CustomH2', parent=styles['Heading2'], fontName='Helvetica-Bold', fontSize=12, spaceAfter=10, spaceBefore=15)
    body_style = ParagraphStyle(name='CustomBody', parent=styles['Normal'], fontName='Helvetica', fontSize=10, alignment=TA_JUSTIFY, spaceAfter=10)
    
    story = []
    
    story.append(Paragraph("MERIDIAN CABLES MAROC SA", title_style))
    story.append(Paragraph("POLITIQUE DE SÉCURITÉ DES SYSTÈMES D'INFORMATION", title_style))
    story.append(Paragraph("Document N°: POL-IT-2019-001<br/>Version: 1.8<br/>DERNIÈRE RÉVISION: Mars 2019<br/>PROCHAINE RÉVISION PRÉVUE: Mars 2021 [ÉCHUE - NON RÉVISÉE]<br/>Propriétaire: Direction des Systèmes d'Information<br/>Classification: Confidentiel", body_style))
    story.append(Spacer(1, 20))
    
    story.append(Paragraph("Section 1 — Politique de Mots de Passe (Password Policy)", h2_style))
    story.append(Paragraph("Les mots de passe doivent comporter un minimum de 8 caractères. Ils doivent être changés obligatoirement tous les 90 jours. Les exigences de complexité imposent l'utilisation combinée de caractères alphanumériques et de caractères spéciaux. La réutilisation des 5 derniers mots de passe est bloquée par le système. L'authentification à deux facteurs est réservée et requise pour les administrateurs systèmes.", body_style))
    
    story.append(Paragraph("Section 2 — Gestion des Accès (Access Management)", h2_style))
    story.append(Paragraph("Nous appliquons strictement le principe du moindre privilège. L'accès aux systèmes est accordé uniquement en fonction des exigences du poste de travail. L'ajout d'un nouvel utilisateur nécessite l'approbation formelle de son responsable direct et des ressources humaines. Tout accès doit être révoqué dans les 24 heures suivant le départ d'un employé. Une revue trimestrielle des accès est effectuée par l'équipe IT.", body_style))
    
    story.append(Paragraph("Section 3 — Classification des Données (Data Classification)", h2_style))
    story.append(Paragraph("Les données de l'entreprise sont réparties en quatre niveaux de classification : Public, Interne, Confidentiel, et Très Confidentiel. Des procédures strictes de manipulation s'appliquent à chaque niveau. Les données classées comme confidentielles ne doivent en aucun cas être transmises par courrier électronique à l'extérieur sans protection adéquate.", body_style))
    
    story.append(Paragraph("Section 4 — Réponse aux Incidents (Incident Response)", h2_style))
    story.append(Paragraph("Tous les incidents de sécurité doivent être signalés immédiatement au service d'assistance IT. Un tri préliminaire doit être effectué dans les 4 heures suivant le signalement. Des procédures d'escalade sont prévues pour le traitement des incidents critiques. Une revue post-incident est systématiquement requise pour tout incident de priorité P1. L'équipe peut être contactée via : it.security@meridian-cables.ma.", body_style))
    
    story.append(Paragraph("Section 5 — Sécurité Physique (Physical Security)", h2_style))
    story.append(Paragraph("L'accès à la salle des serveurs est strictement limité et contrôlé par badge électronique, avec une surveillance par caméras CCTV en continu. Une politique de bureau propre est imposée à tous les employés. Le verrouillage de l'écran de l'ordinateur est obligatoire dès que l'utilisateur quitte son poste de travail. L'accès des visiteurs à la salle des serveurs est formellement interdit.", body_style))
    
    story.append(Paragraph("Section 6 — Sauvegardes (Backup Policy)", h2_style))
    story.append(Paragraph("Les systèmes critiques de l'entreprise font l'objet d'une sauvegarde de manière quotidienne. Pour assurer une redondance sécurisée, les bandes de sauvegarde sont systématiquement conservées dans une installation hors site, protégeant ainsi nos informations vitales contre les sinistres locaux.", body_style))
    
    # Pad to make it longer
    for _ in range(4):
        story.append(PageBreak())
        story.append(Paragraph("Section Annexe — Directives d'Utilisation des Systèmes", h2_style))
        story.append(Paragraph("Les équipements informatiques fournis par l'entreprise demeurent la propriété exclusive de Meridian Cables Maroc SA. Leur utilisation doit être réservée en priorité aux tâches professionnelles. Toute altération des configurations de sécurité matérielle ou logicielle par l'utilisateur final est strictement prohibée. " * 10, body_style))

    doc.build(story, onFirstPage=make_bg_watermark, onLaterPages=make_bg_watermark)
    print("[OK] it_security_policy.pdf saved")

